tool_input.old_string:
.user-menu-trigger {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  cursor: pointer;
  padding: 4px;
  min-width: 0;
  max-width: 100%;
}

.user-menu-trigger:hover {
  transition: background-color 200ms;
}

.user-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  flex-shrink: 0;
}

.user-nickname {
  font-size: 14px;
  font-weight: 400;
  line-height: 32px;
  color: var(--menu-text-color, white);
  margin-left: 7px;
  min-width: 0;
  flex: 1 1 auto;
  max-width: min(240px, 32vw);
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
  padding-right: 10px;
}

tool_input.new_string:
.user-menu-trigger {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  cursor: pointer;
  padding: 0;
  width: 100%;
  height: 100%;
  min-width: 0;
}

.user-menu-trigger:hover {
  transition: background-color 200ms;
}

.user-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.user-avatar-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  color: #fff;
  background-color: #2e78b8;
  font-size: 23px;
  flex-shrink: 0;
}

.user-nickname {
  max-width: 78px;
  color: var(--menu-text-color, white);
  font-size: 14px;
  font-weight: 400;
  line-height: 18px;
  text-align: center;
  white-space: nowrap;
}
